import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // Calculate plane dimensions from atlas region aspect ratio
  const sourceRect = config.atlasRegion?.sourceRect || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = sourceRect.width / sourceRect.height;
  const planeWidth = 2.6; // reasonable scale for the hub
  const planeHeight = planeWidth / aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    side: THREE.DoubleSide,
    transparent: true,
    depthWrite: false,
  });

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(0, 0, 0);
  group.add(mesh);

  // Load texture and apply it
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // If the texture is part of an atlas, set repeat/offset
      if (sourceRect.width && sourceRect.height && tex.image) {
        const imgW = tex.image.width;
        const imgH = tex.image.height;
        if (imgW && imgH) {
          tex.repeat.set(sourceRect.width / imgW, sourceRect.height / imgH);
          tex.offset.set(sourceRect.x / imgW, sourceRect.y / imgH);
          tex.needsUpdate = true;
        }
      }
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Apply visual spec colors to gradient? No – the texture provides the visual.
  // No text content, no primitives.

  // Event handlers (none)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) {
      material.map.dispose();
    }
    // No GSAP timelines to kill
  };

  return group;
}
